VAR
    Overload_Timer : TON;
END_VAR

Overload_Timer(IN := (Motor_Current > 47.7) AND Motor_Running, PT := T#10S);

IF Overload_Timer.Q THEN
    Overload_Alarm := TRUE;
    Motor_Stop := TRUE;
END_IF;

IF Fault_Reset THEN
    Overload_Alarm := FALSE;
    Motor_Stop := FALSE;
END_IF;

